const checks = {};

// Check if key files exist
const fs = require('fs');
const criticalFiles = [
  '/home/user/Orbital/master_brief.md',
  '/home/user/Orbital/CLAUDE.md',
  '/home/user/Orbital/package.json',
  '/home/user/Orbital/nova/EMPIRE.md'
];

checks.files = criticalFiles.every(f => {
  try { fs.accessSync(f); return true; } catch { return false; }
});

// Check git status
const { execSync } = require('child_process');
try {
  const status = execSync('cd /home/user/Orbital && git status --porcelain', { encoding: 'utf8' });
  checks.git_clean = status.trim().length === 0;
  checks.git_dirty_files = status.trim().split('\n').filter(Boolean).length;
} catch (e) {
  checks.git_clean = false;
  checks.git_error = e.message;
}

// Count media files
try {
  const media = fs.readdirSync('/home/user/Orbital/nova/media/').filter(f => f.endsWith('.png') || f.endsWith('.mp4'));
  checks.media_count = media.length;
} catch { checks.media_count = 0; }

// Count memory entries
try {
  const learnings = fs.readFileSync('/home/user/Orbital/nova/memory/learnings.jsonl', 'utf8').trim().split('\n').length;
  checks.memory_entries = learnings;
} catch { checks.memory_entries = 0; }

checks.ts = new Date().toISOString();
checks.status = checks.files ? 'healthy' : 'degraded';

return [{ json: checks }];

const fs = require('fs');
const state = {
  lastUpdated: $json.ts,
  health: $json.status,
  git: { clean: $json.git_clean, dirtyFiles: $json.git_dirty_files || 0 },
  media: { totalAssets: $json.media_count },
  memory: { totalEntries: $json.memory_entries },
  divisions: {
    creative: { status: 'configured', lastCheck: $json.ts },
    rd: { status: 'configured', lastCheck: $json.ts },
    ops: { status: 'running', lastCheck: $json.ts },
    cfo: { status: 'configured', lastCheck: $json.ts },
    media: { status: 'configured', lastCheck: $json.ts }
  }
};
fs.writeFileSync('/home/user/Orbital/nova/memory/empire_state.json', JSON.stringify(state, null, 2));
return [{ json: { written: true } }];
